<template>
  <section class="extension-panel" v-loading="loading">
    <div class="panel-heading"><h3>拓展课</h3><el-button type="primary" size="small" @click="openCreate">新建拓展班</el-button><el-button size="small" @click="load">刷新</el-button><span v-if="collapsible" class="panel-toggle" @click="collapsed = !collapsed">{{ collapsed ? '展开' : '收起' }}</span></div>
    <div v-show="!collapsed" class="panel-body">
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-empty v-if="!loading && !classes.length" description="还没有拓展班，可跨年级添加本校学生" :image-size="52"><el-button type="primary" @click="openCreate">去创建拓展班</el-button></el-empty>
    <el-table v-else :data="classes" size="small">
      <el-table-column prop="class_name" label="拓展班" min-width="150" />
      <el-table-column prop="member_count" label="成员" width="70" />
      <el-table-column label="当前签到课" min-width="160"><template #default="{ row }">{{ row.dashboard?.currentLesson?.lesson_title || '暂无' }}<span v-if="row.dashboard?.currentLesson"> · {{ row.dashboard.checkedIn }}/{{ row.dashboard.total }}</span></template></el-table-column>
      <el-table-column label="状态" width="90"><template #default="{ row }">{{ row.status === 'ACTIVE' ? '进行中' : '已归档' }}</template></el-table-column>
      <el-table-column label="操作" min-width="300"><template #default="{ row }"><template v-if="row.status === 'ACTIVE' && !row.legacy_flag"><el-button link type="primary" @click="openLesson(row)">新建签到课</el-button><el-button link type="primary" @click="openMembers(row)">成员管理</el-button><el-button link type="primary" @click="python(row)">Python 题单</el-button><el-button link @click="openEdit(row)">编辑</el-button><el-button link type="danger" @click="archive(row)">归档</el-button></template><el-button link type="primary" @click="showDashboard(row)">{{ row.legacy_flag ? '历史只读' : '签到情况' }}</el-button></template></el-table-column>
    </el-table>
    </div>
    <el-dialog v-model="createVisible" :title="editing ? '编辑拓展班' : '新建拓展班'" width="min(460px,94vw)" append-to-body>
      <el-form label-width="90px"><el-form-item label="班级名称" required><el-input v-model="form.className" maxlength="100" /></el-form-item><el-form-item v-if="admin && !editing" label="负责人" required><el-select v-model="form.ownerUserId" filterable placeholder="选择本校教师"><el-option v-for="t in teachers" :key="t.user_id" :label="t.nick_name" :value="t.user_id" /></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.remark" type="textarea" maxlength="500" /></el-form-item></el-form>
      <el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false" /><template #footer><el-button @click="createVisible = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!form.className.trim() || (admin && !editing && !form.ownerUserId)" @click="saveClass">保存拓展班</el-button></template>
    </el-dialog>
    <el-drawer v-model="membersVisible" :title="`${selected?.class_name || ''} · 成员管理`" size="min(760px,100vw)" append-to-body>
      <el-alert v-if="memberError" :title="memberError" type="error" :closable="false" />
      <h4>当前成员（{{ members.length }}人）</h4><el-table :data="members" size="small"><el-table-column prop="student_name" label="姓名" /><el-table-column prop="student_no" label="学号" /><el-table-column label="原班级"><template #default="{ row }">{{ row.entry_year }}级{{ row.class_code }}班</template></el-table-column><el-table-column width="70"><template #default="{ row }"><el-button link type="danger" :disabled="saving" @click="remove(row)">移出</el-button></template></el-table-column></el-table>
      <h4>添加本校学生</h4><el-input v-model="keyword" clearable placeholder="按姓名、学号或原班级搜索" @keyup.enter="search"><template #append><el-button :loading="searching" @click="search">搜索</el-button></template></el-input>
      <el-table :data="candidates" v-loading="searching" size="small" @selection-change="rows => chosen = rows"><el-table-column type="selection" :selectable="row => !row.extension_class_id" width="45" /><el-table-column prop="student_name" label="姓名" /><el-table-column prop="student_no" label="学号" /><el-table-column label="原班级"><template #default="{ row }">{{ row.entry_year }}级{{ row.class_code }}班</template></el-table-column><el-table-column label="拓展班"><template #default="{ row }">{{ row.extension_class_name || '未加入' }}</template></el-table-column></el-table>
      <div v-if="candidatesTruncated" class="hint">结果较多，只显示前 200 人；请输入更精确的姓名或学号。</div>
      <p class="hint">已在其他拓展班的学生需先移出；本节课建课后加入的学生，从下一节课开始签到。</p><el-button type="primary" :loading="saving" :disabled="!chosen.length" @click="add">加入所选 {{ chosen.length || '' }} 名学生</el-button>
    </el-drawer>
    <el-dialog v-model="lessonVisible" title="新建签到课" width="min(460px,94vw)" append-to-body><p>{{ selected?.class_name }} · 保存后替换当前课，旧课及名单保留。</p><el-form label-width="90px"><el-form-item label="课程名" required><el-input v-model="lesson.lessonTitle" maxlength="100" /></el-form-item><el-form-item label="教师说明"><el-input v-model="lesson.remark" type="textarea" maxlength="500" /></el-form-item><el-form-item label="日期" required><el-date-picker v-model="lesson.lessonDate" type="date" value-format="YYYY-MM-DD" /></el-form-item></el-form><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false" /><template #footer><el-button @click="lessonVisible = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!lesson.lessonTitle.trim() || !lesson.lessonDate" @click="saveLesson">保存并发布签到课</el-button></template></el-dialog>
    <el-dialog v-model="dashboardVisible" :title="`${selected?.class_name || ''} · 签到与历史`" width="min(740px,96vw)" append-to-body><div v-loading="dashboardLoading"><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false" /><template v-if="dashboard"><p v-if="dashboard.currentLesson">{{ dashboard.currentLesson.lesson_title }} · 已签到 {{ dashboard.checkedIn }}/{{ dashboard.total }} 人</p><el-table :data="dashboard.roster || []" size="small"><el-table-column prop="student_name" label="姓名" /><el-table-column prop="student_no" label="学号" /><el-table-column label="签到时间"><template #default="{ row }">{{ row.checkin_time ? String(row.checkin_time).replace('T',' ').slice(0,19) : '未签到' }}</template></el-table-column></el-table><h4>历史签到课</h4><el-table :data="dashboard.lessons || []" size="small"><el-table-column prop="lesson_title" label="课程" /><el-table-column prop="lesson_date" label="日期" /><el-table-column width="100"><template #default="{ row }"><el-button link @click="historyRoster(row)">查看名单</el-button></template></el-table-column></el-table><template v-if="dashboard.plans"><h4>历史 Python 题单</h4><el-table :data="dashboard.plans"><el-table-column prop="plan_name" label="题单" /><el-table-column width="110"><template #default="{ row }"><el-button link type="primary" @click="legacyPython(row)">查看学情</el-button></template></el-table-column></el-table></template></template></div></el-dialog>
  </section>
</template>
<script setup>
import { ref, reactive, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import useUserStore from '@/store/modules/user'
import * as api from '@/api/business/extension'
defineProps({ collapsible: { type: Boolean, default: false } })
const router = useRouter(), user = useUserStore()
const admin = computed(() => user.roles.includes('admin'))
const collapsed = ref(false)
const classes = ref([]), loading = ref(false), saving = ref(false), error = ref(''), dialogError = ref(''), memberError = ref('')
const createVisible = ref(false), editing = ref(null), teachers = ref([]), form = reactive({ className: '', ownerUserId: null, remark: '' })
const selected = ref(null), membersVisible = ref(false), members = ref([]), candidates = ref([]), candidatesTruncated = ref(false), chosen = ref([]), keyword = ref(''), searching = ref(false)
const lessonVisible = ref(false), lesson = reactive({ lessonTitle: '', remark: '', lessonDate: '' })
const dashboardVisible = ref(false), dashboard = ref(null), dashboardLoading = ref(false)
async function load() { loading.value = true; error.value = ''; try { classes.value = (await api.getExtensionClasses()).data || [] } catch (e) { error.value = e.message || '加载失败，请刷新重试' } finally { loading.value = false } }
async function openCreate() { editing.value = null; Object.assign(form, { className: '', ownerUserId: null, remark: '' }); dialogError.value = ''; createVisible.value = true; if (admin.value) try { teachers.value = (await api.getExtensionTeachers()).data || [] } catch (e) { dialogError.value = e.message || '教师加载失败' } }
function openEdit(row) { editing.value = row; Object.assign(form, { className: row.class_name, remark: row.remark || '' }); dialogError.value = ''; createVisible.value = true }
async function saveClass() { saving.value = true; dialogError.value = ''; try { if (editing.value) await api.updateExtensionClass(editing.value.extension_class_id, form); else await api.createExtensionClass(form); createVisible.value = false; ElMessage.success('拓展班已保存'); await load() } catch (e) { dialogError.value = e.message || '保存失败，请重试' } finally { saving.value = false } }
async function archive(row) { try { await ElMessageBox.confirm('归档后释放成员归属，保留历史签到和题单。是否归档？', '归档拓展班', { type: 'warning' }) } catch { return } try { await api.archiveExtensionClass(row.extension_class_id); await load() } catch (e) { error.value = e.message || '归档失败' } }
async function openMembers(row) { selected.value = row; membersVisible.value = true; memberError.value = ''; candidates.value = []; candidatesTruncated.value = false; chosen.value = []; keyword.value = ''; try { members.value = (await api.getExtensionMembers(row.extension_class_id)).data || []; await search() } catch (e) { memberError.value = e.message || '成员加载失败' } }
async function search() { searching.value = true; memberError.value = ''; try { const payload = (await api.getExtensionCandidates(keyword.value)).data || {}; candidates.value = payload.items || []; candidatesTruncated.value = !!payload.truncated; chosen.value = [] } catch (e) { memberError.value = e.message || '搜索失败' } finally { searching.value = false } }
async function add() { saving.value = true; memberError.value = ''; try { await api.addExtensionMembers(selected.value.extension_class_id, chosen.value.map(s => s.student_id)); members.value = (await api.getExtensionMembers(selected.value.extension_class_id)).data || []; await search(); await load(); ElMessage.success('成员已加入，下节课起可签到') } catch (e) { memberError.value = e.message || '加入失败' } finally { saving.value = false } }
async function remove(row) { try { await ElMessageBox.confirm(`将${row.student_name}移出？历史签到仍保留。`, '移出成员') } catch { return } saving.value = true; try { await api.removeExtensionMember(selected.value.extension_class_id, row.student_id); members.value = (await api.getExtensionMembers(selected.value.extension_class_id)).data || []; await search(); await load() } catch (e) { memberError.value = e.message || '移出失败' } finally { saving.value = false } }
function openLesson(row) { selected.value = row; dialogError.value = ''; Object.assign(lesson, { lessonTitle: '', remark: '', lessonDate: new Date().toLocaleDateString('sv-SE') }); lessonVisible.value = true }
async function saveLesson() { saving.value = true; dialogError.value = ''; try { await api.createExtensionLesson(selected.value.extension_class_id, lesson); lessonVisible.value = false; ElMessage.success('签到课已发布，学生可在拓展课空间签到'); await load() } catch (e) { dialogError.value = e.message || '发布失败' } finally { saving.value = false } }
async function showDashboard(row) { selected.value = row; dashboardVisible.value = true; dashboard.value = null; dialogError.value = ''; dashboardLoading.value = true; try { dashboard.value = (await (row.legacy_flag ? api.getExtensionLegacy(row.extension_class_id) : api.getExtensionDashboard(row.extension_class_id))).data } catch (e) { dialogError.value = e.message || '签到加载失败' } finally { dashboardLoading.value = false } }
async function historyRoster(row) { dialogError.value = ''; try { const res = await api.getExtensionRoster(selected.value.extension_class_id, row.lesson_id); dashboard.value = { ...dashboard.value, currentLesson: row, roster: res.data, total: res.data.length, checkedIn: res.data.filter(s => s.checkin_time).length } } catch (e) { dialogError.value = e.message || '名单加载失败' } }
function legacyPython(row) { router.push({ path: '/python-practice', query: { extensionClassId: selected.value.extension_class_id, legacyPlanId: row.plan_id } }) }
function python(row) { router.push({ path: '/python-practice', query: { extensionClassId: row.extension_class_id } }) }
onMounted(load)
</script>
<style scoped>
.extension-panel{--el-color-primary:#1f5fbf;border:1px solid #dce3ed;border-radius:4px;padding:14px;margin:12px 0;background:#fff}.panel-heading{display:flex;align-items:center;gap:10px;margin-bottom:10px}.panel-heading h3{margin:0 auto 0 0;font-size:16px;color:#1f5fbf}.panel-toggle{color:#409eff;font-size:13px;cursor:pointer;user-select:none;white-space:nowrap}.hint{font-size:13px;color:#606266}.extension-panel :deep(.el-button+.el-button){margin-left:8px}
</style>
